#include "stdafx.h"#include "ModbusTcpDebug.h"#include "ModbusTcpDoc.h"// KModbusTcpDocIMPLEMENT_DYNCREATE(KModbusTcpDoc, CDocument)KModbusTcpDoc::KModbusTcpDoc(){  m_Notifiers.insert( notifiers_vector::value_type( eSelectedDR, CreateNotifier() ) );  m_Notifiers.insert( notifiers_vector::value_type( eSelectedBlock, CreateNotifier() ) );}BOOL KModbusTcpDoc::OnNewDocument(){	if (!CDocument::OnNewDocument())		return FALSE;	return TRUE;}KModbusTcpDoc::~KModbusTcpDoc(){}void KModbusTcpDoc::operator = ( const SPrjCfg &thr ){  m_Config = thr;}bool KModbusTcpDoc::IsEmpty(){  return true;}const SPrjCfg& KModbusTcpDoc::GetConfig(){  return m_Config;}notifier_ptr KModbusTcpDoc::CreateNotifier(){  return notifier_ptr( new notifier(this) );}INotifier* KModbusTcpDoc::GetEventNotifier( int id ){  notifiers_vector::iterator iter = m_Notifiers.find( id );  if( iter==m_Notifiers.end() )  {    ASSERT( 0 );    return NULL;  }  return iter->second.get();}BEGIN_MESSAGE_MAP(KModbusTcpDoc, CDocument)END_MESSAGE_MAP()// KModbusTcpDoc diagnostics#ifdef _DEBUGvoid KModbusTcpDoc::AssertValid() const{	CDocument::AssertValid();}#ifndef _WIN32_WCEvoid KModbusTcpDoc::Dump(CDumpContext& dc) const{	CDocument::Dump(dc);}#endif#endif //_DEBUG#ifndef _WIN32_WCE// KModbusTcpDoc serializationvoid KModbusTcpDoc::Serialize(CArchive& ar){	if (ar.IsStoring())	{		// TODO: add storing code here	}	else	{		// TODO: add loading code here	}}#endif// KModbusTcpDoc commands